<?php
declare(strict_types=1);
$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim(trim($v),"\"'");}
function c(array $e,string $p,string $db):PDO{return new PDO('mysql:host='.$e[$p.'_DB_HOST'].';port='.$e[$p.'_DB_PORT'].';dbname='.$db.';charset=utf8mb4',$e[$p.'_DB_USERNAME'],$e[$p.'_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
$t=c($env,'GPT','gatlas_dbp');$report=['database'=>'gatlas_dbp','schema'=>$t->query("SELECT DEFAULT_CHARACTER_SET_NAME,DEFAULT_COLLATION_NAME FROM information_schema.schemata WHERE schema_name='gatlas_dbp'")->fetch(),'objects'=>[],'security'=>[],'integrity'=>[],'isolation'=>[]];
$report['objects']['tables']=(int)$t->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='gatlas_dbp' AND table_type='BASE TABLE'")->fetchColumn();$report['objects']['views']=(int)$t->query("SELECT COUNT(*) FROM information_schema.views WHERE table_schema='gatlas_dbp'")->fetchColumn();$report['objects']['routines']=(int)$t->query("SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema='gatlas_dbp'")->fetchColumn();
$report['objects']['non_official_table_collations']=$t->query("SELECT table_name,table_collation FROM information_schema.tables WHERE table_schema='gatlas_dbp' AND table_type='BASE TABLE' AND table_collation IS NOT NULL AND table_collation<>'utf8mb4_0900_ai_ci' ORDER BY table_name")->fetchAll();
$report['security']['users']=(int)$t->query('SELECT COUNT(*) FROM usuarios')->fetchColumn();$report['security']['groups']=(int)$t->query('SELECT COUNT(*) FROM grupos')->fetchColumn();$report['security']['admin']=(int)$t->query("SELECT COUNT(*) FROM usuarios u JOIN perfis p ON p.codperfil=u.codperfil WHERE u.userid='admin' AND p.codigo='ADMINISTRADOR' AND u.ativo=1")->fetchColumn();$report['security']['duplicate_userids']=(int)$t->query("SELECT COUNT(*) FROM (SELECT userid FROM usuarios GROUP BY userid HAVING COUNT(*)>1) d")->fetchColumn();$report['security']['menus']=(int)$t->query('SELECT COUNT(*) FROM menus')->fetchColumn();$report['security']['permissions']=(int)$t->query('SELECT COUNT(*) FROM perfil_menus')->fetchColumn();
$report['integrity']['migration_records']=(int)$t->query('SELECT COUNT(*) FROM registros_migracao WHERE status=\'CONCLUIDA\'')->fetchColumn();$report['integrity']['migration_errors']=$t->query("SELECT codigo_migracao,detalhes FROM registros_migracao WHERE status<>'CONCLUIDA'")->fetchAll();$report['integrity']['orphan_users']=(int)$t->query('SELECT COUNT(*) FROM usuarios u LEFT JOIN perfis p ON p.codperfil=u.codperfil WHERE u.codperfil IS NOT NULL AND p.codperfil IS NULL')->fetchColumn();
$foreign=$t->query("SELECT COUNT(*) FROM information_schema.views WHERE table_schema='gatlas_dbp' AND (view_definition LIKE '%green_atlas%' OR view_definition LIKE '%green_modelo%' OR view_definition LIKE '%green_atlas_seguranca%')")->fetchColumn();$routineForeign=$t->query("SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema='gatlas_dbp' AND (routine_definition LIKE '%green_atlas%' OR routine_definition LIKE '%green_modelo%' OR routine_definition LIKE '%green_atlas_seguranca%')")->fetchColumn();$report['isolation']=['views_external_references'=>(int)$foreign,'routines_external_references'=>(int)$routineForeign];
$central=c($env,'GUNIVERSAL',$env['GUNIVERSAL_DB_DATABASE']??'guniversal_dbp');$report['central']=$central->query("SELECT codigo,nome,banco_dados,status FROM empresa WHERE codigo='ATLAS'")->fetch();
$out=__DIR__.'/../docs/validacao_atlas_'.date('Ymd').'.json';file_put_contents($out,json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL);echo json_encode(['report'=>$out,'summary'=>$report],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;
